	if b.filterActive {
		switch msg.String() {
		case "esc", "enter":
			b.filterActive = false
			b.filterInput.Blur()
			b.rebuildTagTable()
			b.resizeTagTable()
			return b, nil
		}
		return b.delegateUpdate(msg)
	}

	switch msg.String() {
	case "esc":
		b.state = browserStateInput
		b.tagTable.Blur()
		b.updateFocus()
		return b, nil
	case "/":
		b.filterActive = true
		b.filterInput.Focus()
		b.resizeTagTable()
		return b, nil
	case "r":
		b.cycleRegistryFilter()
		return b, nil
	case "enter":
		return b.openTagScanDetails()
	case keymap.Get:
		return b.pullSelectedTag()
	case keymap.Scan:
		return b.requestDirectScan()
	}
	// Navigation and `.` are the table's. `/` never reaches it: the browser's
	// own filter took the key two cases above, and the table declares no
	// searchable column, so it would decline it anyway.
	return b, b.tagTable.Update(msg)
}"},{"rank":6,"score":35.1413,"file_path":"internal/app/app.go","start_line":507,"end_line":511,"focus_line":509,"snippet_start_line":508,"snippet_end_line":509,"symbol_start_line":344,"symbol_end_line":526,"language":"Go","kind":"method","symbol_id":"local/devdesk:Go:internal/app/app.go:method:App.Update","symbol_name":"Update","qualified_name":"App.Update","signature":"func (a *App) Update(msg tea.Msg) (tea.Model, tea.Cmd)","signals":["body","symbol-usage"],"snippet":"	case uiviewer.OpenRequestMsg:
