package status

import (
	"context"
	"time"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/status"
)

// tickCmd returns a command that ticks every second
func tickCmd() tea.Cmd {
	return tea.Tick(1*time.Second, func(t time.Time) tea.Msg {
		return TickMsg(t)
	})
}

// checkComponents launches the check of all components (async)
func checkComponents(cfg *config.Config) tea.Cmd {
	return func() tea.Msg {
		// Create the checker
		checker := status.NewChecker(time.Duration(cfg.Status.Timeout))

		// Launch the checks
		ctx := context.Background()
		results := checker.CheckAll(ctx, cfg.Status.Components)

		// Return the results
		return CheckCompleteMsg{
			Components: results,
			Timestamp:  time.Now(),
			Err:        nil,
		}
	}
}

// saveComponent saves the config (Rule 110: does NOT modify the config, I/O only)
func saveComponent(cfg *config.Config) tea.Cmd {
	return func() tea.Msg {
		// Save the config (I/O only, no model modification)
		err := config.Save(cfg)
		return ComponentSavedMsg{
			Success: err == nil,
			Error:   err,
		}
	}
}

// deleteComponent saves the config (Rule 110: does NOT modify the config, I/O only)
func deleteComponent(cfg *config.Config) tea.Cmd {
	return func() tea.Msg {
		// Save the config (I/O only, no model modification)
		err := config.Save(cfg)
		return ComponentDeletedMsg{
			Success: err == nil,
			Error:   err,
		}
	}
}

package status

import (
	"time"

	"github.com/charmbracelet/bubbles/spinner"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/status"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/status/components"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// Tab constants
const (
	TabMonitors     = 0
	TabCertificates = 1
)

// Model represents the state of the status view
type Model struct {
	// Configuration
	config          *config.Config
	refreshInterval time.Duration

	// Monitoring state
	components []status.ComponentStatus
	lastCheck  time.Time
	nextCheck  time.Time

	// State flags
	//
	// autoRefresh comes from status.auto_refresh and has no other writer: the
	// setting belongs to the configuration view, and this view had a `space`
	// toggle that shadowed it in memory only — same shape as the +/- interval
	// it lost for the same reason.
	autoRefresh bool
	checking    bool
	// footer is the one line of transient state below the tab bar (Rule 128).
	// This view raises no message; it carries the spinner the check is reported
	// with.
	footer     sharedcomponents.FooterMessage
	firstCheck bool
	error      string

	// Tables. Two datatables plus a focus helper, not a multi-table
	// abstraction: they share a viewport and alternate focus, and that is all
	// they share.
	monitorTable datatable.Model[status.ComponentStatus]
	sslTable     datatable.Model[status.ComponentStatus]
	activeTab    int // TabMonitors or TabCertificates

	// Bubbles components
	spinner       spinner.Model
	componentForm *components.ComponentForm
	confirmModal  *sharedcomponents.ConfirmModal

	// CRUD modes
	selectedIdx int // Index of the component selected for edit/delete

	// filterBar provides text search for the active table (Rule 136)
	filterBar sharedcomponents.FilterBar

	// Terminal dimensions
	width  int
	height int
}

// New creates a new model
func New(cfg *config.Config) Model {
	// Spinner for loading
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	monitorTable := datatable.New(datatable.Config[status.ComponentStatus]{
		Columns:    monitorColumns(),
		SortColumn: columnName,
	})

	sslTable := datatable.New(datatable.Config[status.ComponentStatus]{
		Columns:    sslColumns(),
		SortColumn: -1, // config order, which is the order the user wrote
	})
	sslTable.Blur()

	return Model{
		config:          cfg,
		refreshInterval: time.Duration(cfg.Status.RefreshInterval) * time.Second,
		autoRefresh:     cfg.Status.AutoRefresh,
		checking:        false,
		firstCheck:      true,
		spinner:         s,
		monitorTable:    monitorTable,
		sslTable:        sslTable,
		activeTab:       TabMonitors,
		error:           "",
		filterBar:       sharedcomponents.NewFilterBar(),
	}
}

// Messages Bubble Tea

// TickMsg - Ticks every second to update the countdown
type TickMsg time.Time

// CheckStartedMsg - A check has just started
type CheckStartedMsg struct{}

// CheckCompleteMsg - Result of a check of all components
type CheckCompleteMsg struct {
	Components []status.ComponentStatus
	Timestamp  time.Time
	Err        error
}

// ComponentSavedMsg - A component has been saved
type ComponentSavedMsg struct {
	Success bool
	Error   error
}

// ComponentDeletedMsg - A component has been deleted
type ComponentDeletedMsg struct {
	Success bool
	Error   error
}

package viewer

import (
	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/viewer"
)

// OpenRequestMsg asks the router to open a document. It is what every producer
// emits — workspaces for a file, containers for an inspect or a log — and the
// only thing they have to agree on.
//
// It carries the source rather than the content: the read happens in the
// viewer's own Init, so one place decides what is too large or not text, and one
// place reports it. A producer that loaded the bytes itself would each have to
// answer that question again, and answer it the same way.
type OpenRequestMsg struct {
	Source viewer.Source
}

// DocumentLoadedMsg carries the result of a Load back into Update (Rule 110).
type DocumentLoadedMsg struct {
	Name    string
	Kind    viewer.Kind
	Content []byte
	Err     error
}

// BackToOriginMsg asks the router to return to the view the document was opened
// from. It mirrors security.BackToOriginMsg, and for the same reason: the view
// knows where it came from, the router knows how to get there.
type BackToOriginMsg struct {
	Origin command.ViewType
}

// PagerExitMsg comes back when the system pager or the follow process ends.
type PagerExitMsg struct {
	Err error
}

// ContentCopiedMsg reports the result of copying the document's text to the
// system clipboard (`Y`).
type ContentCopiedMsg struct {
	Err error
}

// IDEOpenedMsg reports the result of handing the document's path to the
// configured IDE (`O`).
type IDEOpenedMsg struct {
	Err error
}

